def envelop_spans(spans, envelopes):
    index = 0
    for envelope in envelopes:
        chunk = []
        while index < len(spans):
            span = spans[index]
            index += 1
            if span.start < envelope.start:
                continue
            elif span.stop <= envelope.stop:
                chunk.append(span)
            else:
                index -= 1
                break
        yield chunk

