def process_input_source(input_source, api_key):
    if input_source.strip().startswith('https://tenor.com/view/'):
        gif_id = input_source.rsplit('-', 1)[-1]
        if gif_id.isdigit():
            input_source = gif_id
        else:
            raise Exception('Bad GIF URL.')

    is_url = input_source.startswith(('http://', 'https://'))

    if not os.path.exists(input_source) and not is_url:
        # get from Tenor GIF API
        params = {'key': api_key}
        if input_source.isdigit():
            endpoint = 'gifs'
            params.update({'ids': input_source})
        elif input_source == '':
            endpoint = 'trending'
            params.update({'limit': 1})
        else:
            endpoint = 'search'
            params.update({'limit': 1, 'q': input_source})

        resp = requests.get(
            'https://api.tenor.com/v1/{}'.format(endpoint),
            params=params
        )

        try:
            resp_json = resp.json()
        except JSONDecodeError:
            raise Exception('A server error occurred.')

        if 'error' in resp_json:
            raise Exception('An error occurred: {}'.format(resp_json['error']))

        results = resp_json.get('results')

        if not results:
            raise Exception('Could not find GIF.')

        input_source = results[0]['media'][0]['mp4']['url']
    return input_source

def from_Note(note, process_octaves=True, standalone=True):
    """Get a Note object and return the LilyPond equivalent in a string.

    If process_octaves is set to False, all data regarding octaves will be
    ignored. If standalone is True, the result can be used by functions
    like to_png and will produce a valid output. The argument is mostly here
    to let from_NoteContainer make use of this function.
    """
    # Throw exception
    if not hasattr(note, "name"):
        return False

    # Lower the case of the name
    result = note.name[0].lower()

    # Convert #'s and b's to 'is' and 'es' suffixes
    for accidental in note.name[1:]:
        if accidental == "#":
            result += "is"
        elif accidental == "b":
            result += "es"

    # Place ' and , for octaves
    if process_octaves:
        oct = note.octave
        if oct >= 4:
            while oct > 3:
                result += "'"
                oct -= 1
        elif oct < 3:
            while oct < 3:
                result += ","
                oct += 1
    if standalone:
        return "{ %s }" % result
    else:
        return result

def valid_beat_duration(duration):
    """Return True when log2(duration) is an integer."""
    if duration == 0:
        return False
    elif duration == 1:
        return True
    else:
        r = duration
        while r != 1:
            if r % 2 == 1:
                return False
            r /= 2
        return True

def bytes_to_int(bytes, byteorder='big'):
    """Simple helper function to convert byte strings into integers."""
    endian = {'big': '>', 'little': '<'}[byteorder]
    chars = struct.unpack(endian + ('B' * len(bytes)), bytes)
    if byteorder == 'big':
        chars = chars[::-1]
    return sum(int(char) * 256 ** i for (i, char) in enumerate(chars))

