def int_to_script_bytes(class_, v):
    if v == 0:
        return b''
    is_negative = (v < 0)
    if is_negative:
        v = -v
    ba = bytearray()
    while v >= 256:
        ba.append(v & 0xff)
        v >>= 8
    ba.append(v & 0xff)
    if ba[-1] >= 128:
        ba.append(0x80 if is_negative else 0)
    elif is_negative:
        ba[-1] |= 0x80
    return bytes(ba)

