def validate_extension_data(data: ExtensionData) -> bool:
    """Verify extension's dependencies and environment.

    :param extensions: an extension to check
    :returns: if extension should be run
    """

    from mopidy import exceptions
    logger.debug("Validating extension: %s", data.extension.ext_name)

    if data.extension.ext_name != data.entry_point.name:
        logger.warning(
            "Disabled extension %(ep)s: entry point name (%(ep)s) "
            "does not match extension name (%(ext)s)",
            {"ep": data.entry_point.name, "ext": data.extension.ext_name},
        )
        return False

    try:
        data.entry_point.require()
    except pkg_resources.DistributionNotFound as exc:
        logger.info(
            "Disabled extension %s: Dependency %s not found",
            data.extension.ext_name,
            exc,
        )
        return False
    except pkg_resources.VersionConflict as exc:
        if len(exc.args) == 2:
            found, required = exc.args
            logger.info(
                "Disabled extension %s: %s required, but found %s at %s",
                data.extension.ext_name,
                required,
                found,
                found.location,
            )
        else:
            logger.info(
                "Disabled extension %s: %s", data.extension.ext_name, exc
            )
        return False

    try:
        data.extension.validate_environment()
    except exceptions.ExtensionError as exc:
        logger.info("Disabled extension %s: %s", data.extension.ext_name, exc)
        return False
    except Exception:
        logger.exception(
            "Validating extension %s failed with an exception.",
            data.extension.ext_name,
        )
        return False

    if not data.config_schema:
        logger.error(
            "Extension %s does not have a config schema, disabling.",
            data.extension.ext_name,
        )
        return False
    elif not isinstance(data.config_schema.get("enabled"), config_lib.Boolean):
        logger.error(
            'Extension %s does not have the required "enabled" config'
            " option, disabling.",
            data.extension.ext_name,
        )
        return False

    for key, value in data.config_schema.items():
        if not isinstance(value, config_lib.ConfigValue):
            logger.error(
                "Extension %s config schema contains an invalid value"
                ' for the option "%s", disabling.',
                data.extension.ext_name,
                key,
            )
            return False

    if not data.config_defaults:
        logger.error(
            "Extension %s does not have a default config, disabling.",
            data.extension.ext_name,
        )
        return False

    return True

def get_worker_count(
    cls,
    runnable_class: t.Type[Runnable],
    resource_request: dict[str, t.Any] | None,
    workers_per_resource: int | float,
) -> int:
    if resource_request is None:
        resource_request = system_resources()

    # use nvidia gpu
    nvidia_gpus = get_resource(resource_request, "nvidia.com/gpu")
    if (
        nvidia_gpus is not None
        and len(nvidia_gpus) > 0
        and "nvidia.com/gpu" in runnable_class.SUPPORTED_RESOURCES
    ):
        return math.ceil(len(nvidia_gpus) * workers_per_resource)

    # use CPU
    cpus = get_resource(resource_request, "cpu")
    if cpus is not None and cpus > 0:
        if "cpu" not in runnable_class.SUPPORTED_RESOURCES:
            logger.warning(
                "No known supported resource available for %s, falling back to using CPU.",
                runnable_class,
            )

        if runnable_class.SUPPORTS_CPU_MULTI_THREADING:
            if isinstance(workers_per_resource, float):
                raise ValueError(
                    "Fractional CPU multi threading support is not yet supported."
                )
            return workers_per_resource

        return math.ceil(cpus) * workers_per_resource

    # this should not be reached by user since we always read system resource as default
    raise ValueError(
        f"No known supported resource available for {runnable_class}. Please check your resource request. "
        "Leaving it blank will allow BentoML to use system resources."
    )

