def write(self, s):
    self._checkClosed()
    if not isinstance(s, text_type):
        raise TypeError("{} expected, got {}".format(
            text_type.__name__,
            type(s).__name__
        ))
    current_pos = self.tell()
    if self.buffer.tell() + len(s.encode('utf-8')) >= self._max_size:
        self.rollover()
    self.buffer.write(s.encode('utf-8'))
    self._tell = current_pos + len(s)

