def parse_subject_alternative_name_extension(certificate: Certificate) -> SubjectAlternativeNameExtension:
    try:
        san_ext = certificate.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME)
        san_ext_value = cast(SubjectAlternativeName, san_ext.value)
    except ExtensionNotFound:
        return SubjectAlternativeNameExtension(dns_names=[], ip_addresses=[])
    except DuplicateExtension:
        # Fix for https://github.com/nabla-c0d3/sslyze/issues/420
        # Not sure how browsers behave in this case but having a duplicate extension makes the certificate invalid
        # so we just return no SANs (likely to make hostname validation fail, which is fine)
        return SubjectAlternativeNameExtension(dns_names=[], ip_addresses=[])

    dns_names = []
    ip_addresses = []
    for san_value in san_ext_value:
        if isinstance(san_value, IPAddress):
            ip_addresses.append(str(san_value.value))
        elif isinstance(san_value, DNSName):
            dns_names.append(san_value.value)
        else:
            pass

    return SubjectAlternativeNameExtension(dns_names=dns_names, ip_addresses=ip_addresses)

def render(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This method accepts the same arguments as the `dict` constructor:
    A dict, a dict subclass or some keyword arguments.  If no arguments
    are given the context will be empty.  These two calls do the same::

        template.render(knights='that say nih')
        template.render({'knights': 'that say nih'})

    This will return the rendered template as a string.
    """
    if self.environment.is_async:
        import asyncio

        close = False

        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = asyncio.new_event_loop()
            close = True

        try:
            return loop.run_until_complete(self.render_async(*args, **kwargs))
        finally:
            if close:
                loop.close()

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(self.root_render_func(ctx))  # type: ignore
    except Exception:
        self.environment.handle_exception()

def find_redirection_file_path(tokens):
    """
    Finds the path of the file
    which the output of a command should be redirected to and
    returns it along with the type of redirection that it is (in a 2-tuple).
    The type of redirection is an enumeration item of type
    `RedirectionType`.
    Returns `None` if no redirection was found.
    Returns `(RedirectionType.quiet, None)` if a redirection should be done
    to nowhere.
    (This can be achieved by using the redirections symbols and providing
    no filepath).
    """
    if len(tokens) < 2:
        return None
    if tokens[-2] == REDIRECTION_APPEND_SYM:
        return (RedirectionType.append, tokens[-1])
    if tokens[-2] == REDIRECTION_SYM:
        return (RedirectionType.truncate, tokens[-1])
    if (
        tokens[-1] == REDIRECTION_APPEND_SYM
        or tokens[-1] == REDIRECTION_SYM
    ):
        return (RedirectionType.quiet, None)
    return None

