def pop(self, *a):
    lists = self.lists
    if len(lists) == 1 and not a:
        return self.lists[0].pop()
    index = a and a[0]
    if index == () or index is None or index == -1:
        ret = lists[-1].pop()
        if len(lists) > 1 and not lists[-1]:
            lists.pop()
    else:
        list_idx, rel_idx = self._translate_index(index)
