async def ensure_permissions(
    self,
    actor: dict,
    permissions: Sequence[Union[Tuple[str, Union[str, Tuple[str, str]]], str]],
):
    """
    permissions is a list of (action, resource) tuples or 'action' strings

    Raises datasette.Forbidden() if any of the checks fail
    """
    assert actor is None or isinstance(actor, dict), "actor must be None or a dict"
    for permission in permissions:
        if isinstance(permission, str):
            action = permission
            resource = None
        elif isinstance(permission, (tuple, list)) and len(permission) == 2:
            action, resource = permission
        else:
            assert (
                False
            ), "permission should be string or tuple of two items: {}".format(
                repr(permission)
            )
        ok = await self.permission_allowed(
            actor,
            action,
            resource=resource,
            default=None,
        )
        if ok is not None:
            if ok:
                return
            else:
                raise Forbidden(action)

def crack_bip32(bip32_pub_node, secret_exponent, path):
    paths = path.split("/")
    while len(paths):
        path = int(paths.pop())
        secret_exponent = ascend_bip32(bip32_pub_node.subkey_for_path("/".join(paths)), secret_exponent, path)
    return bip32_pub_node.__class__(
        bip32_pub_node._chain_code, bip32_pub_node._depth, bip32_pub_node._parent_fingerprint,
        bip32_pub_node._child_index, secret_exponent=secret_exponent)

