    pattern,
    factory=None,
    predicates=(),
    pregenerator=None,
    static=False,
):
    if name in self.routes:
        oldroute = self.routes[name]
        if oldroute in self.routelist:
            self.routelist.remove(oldroute)

    route = Route(name, pattern, factory, predicates, pregenerator)
    if not static:
