def extract_regex(
    regex: Union[str, Pattern[str]], text: str, replace_entities: bool = True
) -> List[str]:
    """Extract a list of strings from the given text/encoding using the following policies:
    * if the regex contains a named group called "extract" that will be returned
    * if the regex contains multiple numbered groups, all those will be returned (flattened)
    * if the regex doesn't contain any group the entire regex matching is returned
    """
    if isinstance(regex, str):
        regex = re.compile(regex, re.UNICODE)

    if "extract" in regex.groupindex:
        # named group
        try:
            extracted = cast(Match[str], regex.search(text)).group("extract")
        except AttributeError:
            strings = []
        else:
            strings = [extracted] if extracted is not None else []
    else:
        # full regex or numbered groups
        strings = regex.findall(text)

    strings = flatten(strings)
    if not replace_entities:
        return strings
    return [w3lib_replace_entities(s, keep=["lt", "amp"]) for s in strings]

def convert(self, value):
    if self._num_digits is not None and len(value) != self._num_digits:
        return None

    # NOTE(kgriffs): int() will accept numbers with preceding or
    # trailing whitespace, so we need to do our own check. Using
    # strip() is faster than either a regex or a series of or'd
    # membership checks via "in", esp. as the length of contiguous
    # numbers in the value grows.
    if value.strip() != value:
        return None

    try:
        value = int(value)
    except ValueError:
        return None

    if self._min is not None and value < self._min:
        return None

    if self._max is not None and value > self._max:
        return None

    return value

