            elif nr_of_strings is None and nr_of_courses is not None:
                result += [
                    y
                    for y in six.itervalues(_known[x][1])
                    if y.count_courses() == nr_of_courses
                ]
            else:
                result += [
                    y
                    for y in six.itervalues(_known[x][1])
                    if y.count_strings() == nr_of_strings
                    and y.count_courses() == nr_of_courses
