async def facet_results(self):
    facet_results = []
    facets_timed_out = []

    qs_pairs = self.get_querystring_pairs()

    facet_size = self.get_facet_size()
    for source_and_config in self.get_configs():
        config = source_and_config["config"]
        source = source_and_config["source"]
        column = config.get("column") or config["simple"]
        facet_sql = """
            select {col} as value, count(*) as count from (
                {sql}
            )
            where {col} is not null
            group by {col} order by count desc, value limit {limit}
        """.format(
            col=escape_sqlite(column), sql=self.sql, limit=facet_size + 1
        )
        try:
            facet_rows_results = await self.ds.execute(
                self.database,
                facet_sql,
                self.params,
                truncate=False,
                custom_time_limit=self.ds.setting("facet_time_limit_ms"),
            )
            facet_results_values = []
            facet_results.append(
                {
                    "name": column,
                    "type": self.type,
                    "hideable": source != "metadata",
                    "toggle_url": self.ds.urls.path(
                        path_with_removed_args(self.request, {"_facet": column})
                    ),
                    "results": facet_results_values,
                    "truncated": len(facet_rows_results) > facet_size,
                }
            )
            facet_rows = facet_rows_results.rows[:facet_size]
            if self.table:
                # Attempt to expand foreign keys into labels
                values = [row["value"] for row in facet_rows]
                expanded = await self.ds.expand_foreign_keys(
                    self.database, self.table, column, values
                )
            else:
                expanded = {}
            for row in facet_rows:
                column_qs = column
                if column.startswith("_"):
                    column_qs = "{}__exact".format(column)
                selected = (column_qs, str(row["value"])) in qs_pairs
                if selected:
                    toggle_path = path_with_removed_args(
                        self.request, {column_qs: str(row["value"])}
                    )
                else:
                    toggle_path = path_with_added_args(
                        self.request, {column_qs: row["value"]}
                    )
                facet_results_values.append(
                    {
                        "value": row["value"],
                        "label": expanded.get((column, row["value"]), row["value"]),
                        "count": row["count"],
                        "toggle_url": self.ds.absolute_url(
                            self.request, self.ds.urls.path(toggle_path)
                        ),
                        "selected": selected,
                    }
                )
        except QueryInterrupted:
            facets_timed_out.append(column)

    return facet_results, facets_timed_out

def to_xml(self):
    parts = ['<?xml version="1.0" encoding="UTF-8"?>',
      '<WebsiteConfiguration xmlns="http://s3.amazonaws.com/doc/2006-03-01/">']
    if self.suffix is not None:
        parts.append(tag('IndexDocument', tag('Suffix', self.suffix)))
    if self.error_key is not None:
        parts.append(tag('ErrorDocument', tag('Key', self.error_key)))
    if self.redirect_all_requests_to is not None:
        parts.append(self.redirect_all_requests_to.to_xml())
    if self.routing_rules:
        parts.append(self.routing_rules.to_xml())
    parts.append('</WebsiteConfiguration>')
    return ''.join(parts)

def create(cls, mod):
    if not cls.modname_to_dist:
        # some packagenames don't match the module names (e.g. PyYAML)
        # so we set up a dict to map from module name to package name
        for dist in pkg_resources.working_set:
            try:
                toplevel_names = dist._get_metadata("top_level.txt")
                for tln in toplevel_names:
                    cls.modname_to_dist[tln] = dist.project_name, dist.version
            except Exception:
                pass

    name, version = cls.modname_to_dist.get(mod.__name__, (mod.__name__, None))

    return PackageDependency(name, version)

