def assert_(self, **kw):
    """Accept an arbitrary set of assertion key/value pairs.  For
    each assertion key/value pair assert that the renderer
    (eg. :func:`pyramid.renderers.render_to_response`)
    received the key with a value that equals the asserted
    value. If the renderer did not receive the key at all, or the
    value received by the renderer doesn't match the assertion
    value, raise an :exc:`AssertionError`."""
    for k, v in kw.items():
        myval = self._received.get(k, _marker)
        if myval is _marker:
            myval = self._implementation._received.get(k, _marker)
            if myval is _marker:
                raise AssertionError(
                    'A value for key "%s" was not passed to the renderer'
                    % k
                )

        if myval != v:
            raise AssertionError(
                '\nasserted value for %s: %r\nactual value: %r'
                % (k, v, myval)
            )
    return True

def int_from_script_bytes(class_, s, require_minimal=False):
    from pycoin.coins.SolutionChecker import ScriptError
    from . import errno
    if len(s) == 0:
        return 0
    s = bytearray(s)
    s.reverse()
    i = s[0]
    v = i & 0x7f
    if require_minimal:
        if v == 0:
            if len(s) <= 1 or ((s[1] & 0x80) == 0):
                raise ScriptError("non-minimally encoded", errno.UNKNOWN_ERROR)
    is_negative = ((i & 0x80) > 0)
    for b in s[1:]:
        v <<= 8
        v += b
    if is_negative:
        v = -v
    return v

def _build_urllib2_request(url, agent, accept_header, etag, modified, referrer, auth, request_headers):
    request = urllib.request.Request(url)
    request.add_header('User-Agent', agent)
    if etag:
        request.add_header('If-None-Match', etag)
    if isinstance(modified, str):
        modified = _parse_date(modified)
    elif isinstance(modified, datetime.datetime):
        modified = modified.utctimetuple()
    if modified:
        # format into an RFC 1123-compliant timestamp. We can't use
        # time.strftime() since the %a and %b directives can be affected
        # by the current locale, but RFC 2616 states that dates must be
        # in English.
        short_weekdays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
        months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
        request.add_header('If-Modified-Since', '%s, %02d %s %04d %02d:%02d:%02d GMT' % (short_weekdays[modified[6]], modified[2], months[modified[1] - 1], modified[0], modified[3], modified[4], modified[5]))
    if referrer:
        request.add_header('Referer', referrer)
    request.add_header('Accept-encoding', 'gzip, deflate')
    if auth:
        request.add_header('Authorization', 'Basic %s' % auth)
    if accept_header:
        request.add_header('Accept', accept_header)
    # use this for whatever -- cookies, special headers, etc
    # [('Cookie','Something'),('x-special-header','Another Value')]
    for header_name, header_value in request_headers.items():
        request.add_header(header_name, header_value)
    request.add_header('A-IM', 'feed')  # RFC 3229 support
    return request

def extract(s, offset, size):
    assert type(s) in (Constant, BitVec)

    if offset == 0 and size == s.size:
        return s

    return BitVec(size, "(_ extract {} {})".format(offset + size - 1, offset), s)

