def extract_paths(content, existing_only=True):
    """Parses paths from a piped input.

    Args:
        content (str): The raw input, can be either a list of files,
            or the output of the strace command.
        existing_only (bool, optional): Requires that files actually exist and aren't directories.
    Returns:
        A list of paths.
    """
    lines = [line.strip() for line in content.splitlines() if len(line.strip())]
    if not len(lines):
        return lines

    # The strace output will start with the exec call of its argument.
    strace_mode = extract_exec_path(lines[0]) is not None
    if not strace_mode:
        return lines

    # Extract files from `open()`, `openat()`, and `exec()` calls.
    paths = set()
    for line in lines:
        path = extract_exec_path(line) or extract_open_path(line) or extract_stat_path(line)
        if path:
            blacklisted = any(path.startswith(directory) for directory in blacklisted_directories)
            if not blacklisted:
                if not existing_only:
                    paths.add(path)
                    continue
                if os.path.exists(path) and os.access(path, os.R_OK) and not os.path.isdir(path):
                    paths.add(path)

    return list(paths)

def _validate_narrow_link(self, parsed_link: ParsedNarrowLink) -> str:
    """
    Returns either an empty string for a successful validation or an
    appropriate validation error.
    """
    if not parsed_link:
        return "The narrow link seems to be either broken or unsupported"

    # Validate stream data.
    if "stream" in parsed_link:
        error = self._validate_and_patch_stream_data(parsed_link)
        if error:
            return error

    # Validate topic name.
    if "topic_name" in parsed_link:
        topic_name = parsed_link["topic_name"]
        stream_id = parsed_link["stream"]["stream_id"]

        if topic_name not in self.model.topics_in_stream(stream_id):
            return "Invalid topic name"

    # Validate message ID for near.
    if "near" in parsed_link["narrow"]:
        message_id = parsed_link.get("message_id")

        if message_id is None:
            return "Invalid message ID"

    return ""

