def deserialize(self, value, display=False):
    value = decode(value).strip()
    validators.validate_required(value, self._required)
    if not value:
        return None

    socket_path = path.get_unix_socket_path(value)
    if socket_path is not None:
        path_str = Path(not self._required).deserialize(socket_path)
        return f"unix:{path_str}"

    try:
        socket.getaddrinfo(value, None)
    except OSError:
        raise ValueError("must be a resolveable hostname or valid IP")

    return value

def to_payload(
    cls,
    batch: ext.NpNDArray,
    batch_dim: int,
) -> Payload:
    # skip 0-dimensional array
    if batch.shape:
        if not (batch.flags["C_CONTIGUOUS"] or batch.flags["F_CONTIGUOUS"]):
            # TODO: use fortan contiguous if it's faster
            batch = np.ascontiguousarray(batch)

        bs: bytes
        concat_buffer_bs: bytes
        indices: list[int]
        bs, concat_buffer_bs, indices = pep574_dumps(batch)
        bs_str = base64.b64encode(bs).decode("ascii")

        return cls.create_payload(
            concat_buffer_bs,
            batch.shape[batch_dim],
            {
                "format": "pickle5",
                "pickle_bytes_str": bs_str,
                "indices": indices,
            },
        )

    return cls.create_payload(
        pickle.dumps(batch),
        batch.shape[batch_dim],
        {"format": "default"},
    )

