    """Validates the given ``values`` using the config schema.

    Returns a tuple with cleaned values and errors.
    """
    from mopidy.config import types
    errors = {}
    result = {}

    for key, value in values.items():
        try:
            result[key] = self[key].deserialize(value)
        except KeyError:  # not in our schema
            errors[key] = "unknown config key."
            suggestion = _did_you_mean(key, self.keys())
            if suggestion:
                errors[key] += f" Did you mean {suggestion!r}?"
        except ValueError as e:  # deserialization failed
            result[key] = None
            errors[key] = str(e)

    for key in self.keys():
        if isinstance(self[key], types.Deprecated):
            result.pop(key, None)
        elif key not in result and key not in errors:
            result[key] = None
            errors[key] = "config key not found."

    return result, errors

def AsDict(self):
    """ Create a dictionary representation of the object. Please see inline
    comments on construction when dictionaries contain TwitterModels. """
    data = {}

    for (key, value) in self.param_defaults.items():

        # If the value is a list, we need to create a list to hold the
        # dicts created by an object supporting the AsDict() method,
        # i.e., if it inherits from TwitterModel. If the item in the list
        # doesn't support the AsDict() method, then we assign the value
        # directly. An example being a list of Media objects contained
        # within a Status object.
        if isinstance(getattr(self, key, None), (list, tuple, set)):
            data[key] = list()
            for subobj in getattr(self, key, None):
                if getattr(subobj, 'AsDict', None):
                    data[key].append(subobj.AsDict())
                else:
                    data[key].append(subobj)

        # Not a list, *but still a subclass of TwitterModel* and
        # and we can assign the data[key] directly with the AsDict()
        # method of the object. An example being a Status object contained
        # within a User object.
        elif getattr(getattr(self, key, None), 'AsDict', None):
            data[key] = getattr(self, key).AsDict()

        # If the value doesn't have an AsDict() method, i.e., it's not
        # something that subclasses TwitterModel, then we can use direct
        # assigment.
        elif getattr(self, key, None):
            data[key] = getattr(self, key, None)
    return data

def flush(self):
    batch_data = {
        self.table.table_name: [
            # We'll insert data here shortly.
        ],
    }

    for put in self._to_put:
        item = Item(self.table, data=put)
        batch_data[self.table.table_name].append({
            'PutRequest': {
                'Item': item.prepare_full(),
            }
        })

    for delete in self._to_delete:
        batch_data[self.table.table_name].append({
            'DeleteRequest': {
                'Key': self.table._encode_keys(delete),
            }
        })

    resp = self.table.connection.batch_write_item(batch_data)
    self.handle_unprocessed(resp)

    self._to_put = []
    self._to_delete = []
    return True

def decode(hrp, addr):
    """Decode a segwit address."""
    hrpgot, data, spec = bech32_decode(addr)
    if hrpgot != hrp:
        return (None, None)
    decoded = convertbits(data[1:], 5, 8, False)
    if decoded is None or len(decoded) < 2 or len(decoded) > 40:
        return (None, None)
    if data[0] > 16:
        return (None, None)
    if data[0] == 0 and len(decoded) != 20 and len(decoded) != 32:
        return (None, None)
    if data[0] == 0 and spec != Encoding.BECH32 or data[0] != 0 and spec != Encoding.BECH32M:
        return (None, None)
    return (data[0], decoded)

