def _statement_matches_resource(statement: dict, resource: str, condition_keys: Optional[CaseInsensitiveDict] = None) -> bool:
    """Helper function, returns True if the given resource is in the given policy statement"""
    if 'Resource' in statement:
        for item in _listify_string(statement['Resource']):
            if _matches_after_expansion(resource, item, condition_keys):
                return True
        return False
    elif 'NotResource' in statement:
        result = True
        for item in _listify_string(statement['NotResource']):
            if _matches_after_expansion(resource, item, condition_keys):
                result = False
                break
        return result
    else:
        return True

def seek(self, pos, mode=0):
    """Traverse from offset to the specified codepoint"""
    self._checkClosed()
    # Seek to position from the start of the file
    if mode == os.SEEK_SET:
        self.buffer.seek(0)
        self._traverse_codepoints(0, pos)
        self._tell = pos
    # Seek to new position relative to current position
    elif mode == os.SEEK_CUR:
        start_pos = self.tell()
        self._traverse_codepoints(self.tell(), pos)
        self._tell = start_pos + pos
    elif mode == os.SEEK_END:
        self.buffer.seek(0)
        dest_position = self.len - pos
        self._traverse_codepoints(0, dest_position)
        self._tell = dest_position
    else:
        raise ValueError(
            "Invalid whence ({0}, should be 0, 1, or 2)".format(mode)
        )
    return self.tell()

def get_distrust_timeline(
    cls, verified_certificate_chain: List[Certificate]
) -> Optional[SymantecDistrustTimelineEnum]:
    from sslyze.plugins.certificate_info._certificate_utils import get_public_key_sha256
    has_whitelisted_cert = False
    has_blacklisted_cert = False

    # Is there a Symantec root certificate in the chain?
    for certificate in verified_certificate_chain:
        key_hash = binascii.hexlify(get_public_key_sha256(certificate)).decode("ascii")
        if key_hash in cls._CA_KEYS_BLACKLIST:
            has_blacklisted_cert = True
        if key_hash in cls._CA_KEYS_WHITELIST:
            has_whitelisted_cert = True

    distrust_enum = None
    if has_blacklisted_cert and not has_whitelisted_cert:
        leaf_cert = verified_certificate_chain[0]
        if leaf_cert.not_valid_before < datetime(year=2016, month=6, day=1):
            distrust_enum = SymantecDistrustTimelineEnum.MARCH_2018
        else:
            distrust_enum = SymantecDistrustTimelineEnum.SEPTEMBER_2018
    return distrust_enum

