def read(self, size=None):
    if size is not None and not isinstance(size, int):
        raise TypeError("size parameter must be an int or long.")

    if size is not None:
        if size == 0:
            return b""
        if size < 0:
            size = None

    self.buf.seek(0, os.SEEK_END)

    if size is None and self.buf.tell():
        ret = self.buf.getvalue()
        self.buf = io.BytesIO()
        return ret
    if size is None:
        d = self.chunk()
        return d

    while self.buf.tell() < size:
        chunk = self.chunk()
        if not chunk:
            ret = self.buf.getvalue()
            self.buf = io.BytesIO()
            return ret
        self.buf.write(chunk)
    data = self.buf.getvalue()
    self.buf = io.BytesIO()
    self.buf.write(data[size:])
    return data[:size]

def merge(self, other):
    """Merge two statements into one."""
    if self.Effect != other.Effect:
        raise ValueError(f"Trying to combine two statements with differing effects: {self.Effect} {other.Effect}")

    effect = self.Effect

    actions = list(sorted(set(self.Action + other.Action), key=lambda action: action.json_repr()))
    resources = list(sorted(set(self.Resource + other.Resource)))

    return Statement(
        Effect=effect,
        Action=actions,
        Resource=resources,
    )

