def to_lines(chunks):
    """Take in data as a sequence of bytes, and yield it, one line at a time.

    Only breaks lines on ``\\n`` (not ``\\r``), and does not add
    a trailing newline.

    For efficiency, passes through anything with a ``readline()`` attribute.
    """
    # hopefully this is good enough for anything mrjob will encounter
    if hasattr(chunks, 'readline'):
        return chunks
    else:
        return _to_lines(chunks)

def deserialize(cls, value, *args, **kwargs):
    value = super(BoolField, cls).deserialize(value)
    if value is None or isinstance(value, cls.TYPE):
        return value

    value = as_string(value).lower()
    if value in cls.TRUE_VALUES:
        return True
    elif value in cls.FALSE_VALUES:
        return False
    else:
        raise ValueError("Value is not boolean")

