def update(self, iterable):
    """given an iterable of (key, val), add them all"""
    if type(iterable) is type(self):
        other = iterable
        for k in other.data:
            if k not in self.data:
                self.data[k] = other.data[k]
            else:
                self.data[k].update(other.data[k])
        for k in other.inv.data:
            if k not in self.inv.data:
                self.inv.data[k] = other.inv.data[k]
            else:
                self.inv.data[k].update(other.inv.data[k])
    elif callable(getattr(iterable, 'keys', None)):
        for k in iterable.keys():
            self.add(k, iterable[k])
    else:
        for key, val in iterable:
            self.add(key, val)
    return

def _pick_error(self, log_interpretation, step_type):
    """Pick probable cause of failure (only call this if job fails)."""
    from mrjob.logs.errors import _pick_error_attempt_ids
    from mrjob.logs.errors import _pick_error
    logs_needed = self._logs_needed_to_pick_error(step_type)

    if self._read_logs() and not all(
            log_type in log_interpretation for log_type in logs_needed):
        log.info('Scanning logs for probable cause of failure...')

        if 'step' in logs_needed:
            self._interpret_step_logs(log_interpretation, step_type)

        if 'history' in logs_needed:
            self._interpret_history_log(log_interpretation)

        if 'task' in logs_needed:
            error_attempt_ids = _pick_error_attempt_ids(log_interpretation)

            self._interpret_task_logs(
                log_interpretation, step_type, error_attempt_ids)

    return _pick_error(log_interpretation)

def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    matches = []

    for sub in enumerate_l33t_subs(
            relevant_l33t_subtable(password, _l33t_table)):
        if not len(sub):
            break

        subbed_password = translate(password, sub)
        for match in dictionary_match(subbed_password, _ranked_dictionaries):
            token = password[match['i']:match['j'] + 1]
            if token.lower() == match['matched_word']:
                # only return the matches that contain an actual substitution
                continue

            # subset of mappings in sub that are in use for this match
            match_sub = {}
            for subbed_chr, chr in sub.items():
                if subbed_chr in token:
                    match_sub[subbed_chr] = chr
            match['l33t'] = True
            match['token'] = token
            match['sub'] = match_sub
            match['sub_display'] = ', '.join(
                ["%s -> %s" % (k, v) for k, v in match_sub.items()]
            )
            matches.append(match)

    matches = [match for match in matches if len(match['token']) > 1]

    return sorted(matches, key=lambda x: (x['i'], x['j']))

