def disconnect(self, receiver=None, name=None, sender=None):
    if receiver:
        name = name or receiver.__name__
    if not name:
        raise ValueError('a receiver or a name must be provided')

    key = (name, sender)
    if key not in self._receivers:
        raise ValueError('receiver named %s for sender=%s not found.' %
                         (name, sender or 'any'))

    self._receivers.remove(key)
    self._receiver_list = [(n, r, s) for n, r, s in self._receiver_list
                           if (n, s) != key]

def remove(self, name):
    """Remove a node from the sort input"""
    self.names.remove(name)
    del self.name2val[name]
    after = self.name2after.pop(name, [])
    if after:
        self.req_after.remove(name)
        for u in after:
            self.order.remove((u, name))
    before = self.name2before.pop(name, [])
    if before:
        self.req_before.remove(name)
        for u in before:
            self.order.remove((name, u))

