def update(self, iterable, **kwargs):
    """Like dict.update() but add counts instead of replacing them, used
    to add multiple items in one call.

    Source can be an iterable of keys to add, or a mapping of keys
    to integer counts.
    """
    if iterable is not None:
        if callable(getattr(iterable, 'iteritems', None)):
            for key, count in iterable.iteritems():
                for i in xrange(count):
                    self.add(key)
        else:
            for key in iterable:
                self.add(key)
    if kwargs:
        self.update(kwargs)

def is_url(value):
    """Must start with http:// or https:// and contain JUST a URL"""
    if not isinstance(value, str):
        return False
    if not value.startswith("http://") and not value.startswith("https://"):
        return False
    # Any whitespace at all is invalid
    if whitespace_re.search(value):
        return False
    return True

