def create_adapter(adapter_name, base_filepath=None):
    """
    Instantiate an adapter and returns it given the name of the adapter as a str.
    Names are:
        - 'rasa': RasaAdapter
        - 'rasa-md' or 'rasamd': RasaMdAdapter
        - 'jsonl': JsonListAdapter
    """
    from chatette.adapters.jsonl import JsonListAdapter
    from chatette.adapters.rasa import RasaAdapter
    from chatette.adapters.rasa_md import RasaMdAdapter
    if adapter_name is None:
        return None
    adapter_name = adapter_name.lower()
    if adapter_name == 'rasa':
        return RasaAdapter(base_filepath)
    elif adapter_name in ('rasa-md', 'rasamd'):
        return RasaMdAdapter(base_filepath)
    elif adapter_name == 'jsonl':
        return JsonListAdapter(base_filepath)
    raise ValueError("Unknown adapter was selected.")

def from_payload(
    cls,
    payload: Payload,
) -> ext.PdDataFrame:
    if payload.meta["with_buffer"]:
        bs_str = t.cast(str, payload.meta["pickle_bytes_str"])
        bs = base64.b64decode(bs_str)
        indices = t.cast(t.List[int], payload.meta["indices"])
        return pep574_loads(bs, payload.data, indices)
    else:
        return pep574_loads(payload.data, b"", [])

def is_rtf(arg, treat_str_as_data=False):
    """ determine whether given file / stream / array represents an rtf file

    arg can be either a file name, a byte stream (located at start), a
    list/tuple or a an iterable that contains bytes.

    For str it is not clear whether data is a file name or the data read from
    it (at least for py2-str which is bytes). Argument treat_str_as_data
    clarifies.
    """
    magic_len = len(RTF_MAGIC)
    if isinstance(arg, UNICODE_TYPE):
        with open(arg, 'rb') as reader:
            return reader.read(len(RTF_MAGIC)) == RTF_MAGIC
    if isinstance(arg, bytes) and not isinstance(arg, str):  # only in PY3
        return arg[:magic_len] == RTF_MAGIC
    if isinstance(arg, bytearray):
        return arg[:magic_len] == RTF_MAGIC
    if isinstance(arg, str):      # could be bytes, but we assume file name
        if treat_str_as_data:
            try:
                return arg[:magic_len].encode('ascii', errors='strict')\
                    == RTF_MAGIC
            except UnicodeError:
                return False
        else:
            with open(arg, 'rb') as reader:
                return reader.read(len(RTF_MAGIC)) == RTF_MAGIC
    if hasattr(arg, 'read'):      # a stream (i.e. file-like object)
        return arg.read(len(RTF_MAGIC)) == RTF_MAGIC
    if isinstance(arg, (list, tuple)):
        iter_arg = iter(arg)
    else:
        iter_arg = arg

    # check iterable
    for magic_byte in zip(RTF_MAGIC):
        try:
            if next(iter_arg) not in magic_byte:
                return False
        except StopIteration:
            return False

    return True  # checked the complete magic without returning False --> match

def text(self):
    from pyramid.util import object_description
    return getattr(
        self.func,
        '__text__',
        'custom predicate: %s' % object_description(self.func),
    )

def save(self, output_file: Union[str, TextIO] = "result.html", file_info: bool = True) -> None:
    if isinstance(output_file, str):
        file_type = output_file.split(".")[-1]

        if file_type == "html":
            with open(output_file, "w", encoding="utf-8") as f:
                self.generate_report(f, output_format="html", file_info=file_info)
        elif file_type == "json":
            with open(output_file, "w", encoding="utf-8") as f:
                self.generate_report(f, output_format="json", file_info=file_info)
        elif file_type == "gz":
            with gzip.open(output_file, "wt") as f:
                self.generate_report(f, output_format="json", file_info=file_info)
        else:
            raise Exception("Only html, json and gz are supported")
    else:
        self.generate_report(output_file, output_format="json", file_info=file_info)

    if isinstance(output_file, str):
        self.final_messages.append(("view_command", {"output_file": os.path.abspath(output_file)}))

    self.print_messages()

def resolve_annotation(
    annotation: Any,
    globalns: Dict[str, Any],
    localns: Optional[Dict[str, Any]],
    cache: Optional[Dict[str, Any]],
) -> Any:
    if annotation is None:
        return type(None)
    if isinstance(annotation, str):
        annotation = ForwardRef(annotation)

    locals = globalns if localns is None else localns
    if cache is None:
        cache = {}
    return evaluate_annotation(annotation, globalns, locals, cache)

def __repr__(self):
    self._assert_resolved()
    return '<%s category %r, discriminator %r>' % (
        self.__class__.__name__,
        self.category_name,
        self.discriminator,
    )

def _match_history_log_path(path, job_id=None):
    """Yield paths/uris of all job history files in the given directories,
    optionally filtering by *job_id*.
    """
    m = _HISTORY_LOG_PATH_RE.match(path)
    if not m:
        return None

    if not (job_id is None or m.group('job_id') == job_id):
        return None

    # TODO: couldn't manage to include .jhist in regex; an optional
    # group has less priority than a non-greedy match, apparently
    return dict(job_id=m.group('job_id'), yarn='.jhist' in m.group('suffix'))

def choose_encoder(accept_header: str) -> Tuple[Callable[[CollectorRegistry], bytes], str]:
    from .openmetrics import exposition as openmetrics
    accept_header = accept_header or ''
    for accepted in accept_header.split(','):
        if accepted.split(';')[0].strip() == 'application/openmetrics-text':
            return (openmetrics.generate_latest,
                    openmetrics.CONTENT_TYPE_LATEST)
    return generate_latest, CONTENT_TYPE_LATEST

def add(self, spec, renderer):
    self.renderers[spec] = renderer
    if ':' in spec:
        package, relative = spec.split(':', 1)
        self.renderers[relative] = renderer

def _parse_progress_from_job_tracker(html_bytes):
    """Pull (map_percent, reduce_percent) from running job from job tracker
    HTML as floats, or return (None, None).

    This assumes at most one running job (designed for EMR).
    """
    # snip out the Running Jobs section (ignore the header)
    start = html_bytes.rfind(b'Running Jobs')
    if start == -1:
        return None, None
    end = html_bytes.find(b'Jobs', start + len(b'Running Jobs'))
    if end == -1:
        end = None

    html_bytes = html_bytes[start:end]

    # search it for percents
    matches = _JOB_TRACKER_HTML_RE.findall(html_bytes)
    if len(matches) >= 2:
        return float(matches[0]), float(matches[1])
    else:
        return None, None

